pub fn lookup(table: &'static [KnownImage], id: &crate::ImageId) -> Option<&'static KnownImage> {
    let sha1 = id.sha1_hex();
    table.iter().find(|k| k.size == id.size && k.crc32 == id.crc32 && k.sha1 == sha1)
}
